@startuml

class Aircraft {
  + Model : string
  + ConstructionYear : date
  + NextInspection : date
}

class Contract {
  + ContractNumber : int
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + AcquisitionID : int
  + Model : string
  + Price : double
  + Options : string
  + Customizations : string
  + DeliveryDate : date
}

class Salesperson {
  + EmployeeID : int
  + Name : string
}

class Airline {
  + AirlineID : int
  + Name : string
  + ParentAirlineID : int
}

Salesperson "1" -- "*" Contract
Contract "1" -- "*" Acquisition
Aircraft "1" -- "0..*" Acquisition
Airline "0..1" -- "0..*" Airline

@enduml

